import pandas as pd

# Parse various date formats
def parse_date(s):
    for fmt in ('%B %d, %Y at %I:%M %p', '%d %b %Y, %H:%M', '%Y-%m-%d %H:%M:%S'):
        try:
            return pd.to_datetime(s, format=fmt)
        except:
            pass
    return pd.NaT

all_reviews['dt'] = all_reviews['date'].apply(parse_date)
print(all_reviews['dt'].isna().sum(), "unparsed of", len(all_reviews))
print(all_reviews[all_reviews['dt'].isna()].head())
